struct LegacyOrder: Decodable {
    let id: String
    let quantity: Int
    enum CodingKeys: String, CodingKey { case id = "order_id"; case quantity = "qty" }

    init(from decoder: Decoder) throws {                 // value-level translation
        let c = try decoder.container(keyedBy: CodingKeys.self)
        id = try c.decode(String.self, forKey: .id)
        quantity = try c.decode(Int.self, forKey: .quantity)
        guard quantity > 0 else { throw DecodingError.dataCorruptedError(
            forKey: .quantity, in: c, debugDescription: "qty must be positive") }
    }
}
